package rs.ucb.komo.concentrationclause.controller;

import static org.springframework.http.MediaType.APPLICATION_JSON_VALUE;

import java.time.OffsetDateTime;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public class ServiceInfoController {

    @GetMapping(path = "/health", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<Map<String, Object>> health() {
        Map<String, Object> response = new LinkedHashMap<>();
        response.put("service", "concentration-clause-service");
        response.put("status", "UP");
        response.put("timestamp", OffsetDateTime.now().toString());
        return ResponseEntity.ok(response);
    }

    @GetMapping(path = "/info", produces = APPLICATION_JSON_VALUE)
    public ResponseEntity<Map<String, Object>> info() {
        Map<String, Object> response = new LinkedHashMap<>();
        response.put("service", "concentration-clause-service");
        response.put("scope", "Owns concentration-clause data, rules, calculation, signal assignment, and collection preparation.");
        response.put("state", "skeleton");
        return ResponseEntity.ok(response);
    }
}

