    'JIR1234-490' = @{ Id='KOMO-US-009'; File='Documentation\Generated\functional-spec\stories\user-story-9-reporting-page.md'; Epic='JIR1234-489' }
}

$epicDocByKey = @{
    'JIR1234-484' = @{ Id='KOMO-E-001'; File=''; Name='Pregled Koncentracionih klauzola za CIB klijente'; Note='Existing Jira epic used for concentration-clause MVP scope.' }
    'JIR1234-489' = @{ Id='KOMO-E-002'; File='Documentation\Generated\functional-spec\epics\epic-2-reporting.md'; Name='Reporting'; Note='' }
