@Entity
@Table(name = "general_covenant_definitions")
public class GeneralCovenantDefinition extends BaseEntity {

    @Column(name = "code", nullable = false, length = 64)
    private String code;

    @Column(name = "display_name", nullable = false, length = 256)
    private String displayName;

    @Lob
    @Column(name = "default_text")
    private String defaultText;

    @Column(name = "measurement_type", nullable = false, length = 32)
    private String measurementType;

    @Column(name = "default_frequency", length = 32)
    private String defaultFrequency;

    @Column(name = "monitored_level", length = 32)
    private String monitoredLevel;

    @Column(name = "requires_bank_consent_flag", nullable = false)
    private Integer requiresBankConsentFlag = 0;

    @Column(name = "requires_notification_flag", nullable = false)
    private Integer requiresNotificationFlag = 0;

    @Column(name = "active_flag", nullable = false)
    private Integer activeFlag = 1;

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    public String getDisplayName() {
        return displayName;
    }

    public void setDisplayName(String displayName) {
        this.displayName = displayName;
    }

    public String getDefaultText() {
        return defaultText;
    }

    public void setDefaultText(String defaultText) {
        this.defaultText = defaultText;
    }

    public String getMeasurementType() {
        return measurementType;
    }

    public void setMeasurementType(String measurementType) {
        this.measurementType = measurementType;
    }

    public String getDefaultFrequency() {
        return defaultFrequency;
    }

    public void setDefaultFrequency(String defaultFrequency) {
        this.defaultFrequency = defaultFrequency;
    }

    public String getMonitoredLevel() {
        return monitoredLevel;
    }

    public void setMonitoredLevel(String monitoredLevel) {
        this.monitoredLevel = monitoredLevel;
    }

    public Integer getRequiresBankConsentFlag() {
        return requiresBankConsentFlag;
    }

    public void setRequiresBankConsentFlag(Integer requiresBankConsentFlag) {
        this.requiresBankConsentFlag = requiresBankConsentFlag;
    }

    public Integer getRequiresNotificationFlag() {
