+package rs.ucb.komo.integration.service.impl;
+
+import java.util.List;
+import java.util.Optional;
+
+import org.springframework.data.jpa.repository.JpaRepository;
+import org.springframework.transaction.annotation.Transactional;
+
+import jakarta.persistence.EntityNotFoundException;
+import rs.ucb.komo.integration.model.BaseEntity;
+import rs.ucb.komo.integration.service.CrudService;
+
+public abstract class DefaultCrudService<T extends BaseEntity> implements CrudService<T> {
+
+    private final JpaRepository<T, Long> repository;
+
+    protected DefaultCrudService(JpaRepository<T, Long> repository) {
+        this.repository = repository;
+    }
+
+    @Override
+    @Transactional(readOnly = true)
+    public List<T> findAll() {
+        return repository.findAll();
+    }
+
+    @Override
+    @Transactional(readOnly = true)
+    public Optional<T> findById(Long id) {
+        return repository.findById(id);
+    }
+
+    @Override
+    @Transactional
+    public T create(T entity) {
+        entity.setId(null);
+        return repository.save(entity);
+    }
+
+    @Override
+    @Transactional
+    public T update(Long id, T entity) {
+        if (!repository.existsById(id)) {
+            throw new EntityNotFoundException("Entity not found: " + id);
+        }
+        entity.setId(id);
+        return repository.save(entity);
+    }
+
+    @Override
+    @Transactional
+    public void deleteById(Long id) {
+        if (!repository.existsById(id)) {
+            throw new EntityNotFoundException("Entity not found: " + id);
+        }
+        repository.deleteById(id);
+    }
+
+    @Override
+    @Transactional(readOnly = true)
+    public boolean existsById(Long id) {
+        return repository.existsById(id);
+    }
+}
