import rs.ucb.komo.concentrationclause.model.BaseEntity;
import rs.ucb.komo.concentrationclause.model.CollectionCase;
import rs.ucb.komo.concentrationclause.model.ConcentrationClause;
import rs.ucb.komo.concentrationclause.model.ConcentrationEvaluation;
import rs.ucb.komo.concentrationclause.model.ConcentrationNotification;
import rs.ucb.komo.concentrationclause.model.WaiverApproval;
import rs.ucb.komo.concentrationclause.service.CollectionCaseService;
import rs.ucb.komo.concentrationclause.service.ConcentrationClauseService;
import rs.ucb.komo.concentrationclause.service.ConcentrationEvaluationService;
import rs.ucb.komo.concentrationclause.service.ConcentrationNotificationService;
import rs.ucb.komo.concentrationclause.service.CrudService;
import rs.ucb.komo.concentrationclause.service.WaiverApprovalService;

@RestController
@RequestMapping(path = "/api", produces = APPLICATION_JSON_VALUE)
@ConditionalOnBean(name = "entityManagerFactory")
public class ConcentrationDataController {

    private final ConcentrationClauseService concentrationClauseService;
    private final ConcentrationEvaluationService concentrationEvaluationService;
    private final ConcentrationNotificationService concentrationNotificationService;
    private final CollectionCaseService collectionCaseService;
    private final WaiverApprovalService waiverApprovalService;

    public ConcentrationDataController(
            ConcentrationClauseService concentrationClauseService,
            ConcentrationEvaluationService concentrationEvaluationService,
            ConcentrationNotificationService concentrationNotificationService,
            CollectionCaseService collectionCaseService,
            WaiverApprovalService waiverApprovalService) {
        this.concentrationClauseService = concentrationClauseService;
        this.concentrationEvaluationService = concentrationEvaluationService;
        this.concentrationNotificationService = concentrationNotificationService;
        this.collectionCaseService = collectionCaseService;
        this.waiverApprovalService = waiverApprovalService;
    }

    @GetMapping("/concentration-clauses")
    public ResponseEntity<List<ConcentrationClause>> listConcentrationClauses() {
        return list(concentrationClauseService);
    }

    @GetMapping("/concentration-clauses/{id}")
    public ResponseEntity<ConcentrationClause> getConcentrationClause(@PathVariable Long id) {
        return get(concentrationClauseService, id);
    }

    @PostMapping(path = "/concentration-clauses", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<ConcentrationClause> createConcentrationClause(@RequestBody ConcentrationClause request) {
        return create(concentrationClauseService, "/api/concentration-clauses", request);
    }

    @PutMapping(path = "/concentration-clauses/{id}", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<ConcentrationClause> updateConcentrationClause(@PathVariable Long id, @RequestBody ConcentrationClause request) {
        return update(concentrationClauseService, id, request);
    }

    @DeleteMapping("/concentration-clauses/{id}")
    public ResponseEntity<Void> deleteConcentrationClause(@PathVariable Long id) {
        return delete(concentrationClauseService, id);
    }

    @GetMapping("/concentration-evaluations")
    public ResponseEntity<List<ConcentrationEvaluation>> listConcentrationEvaluations() {
        return list(concentrationEvaluationService);
    }

    @GetMapping("/concentration-evaluations/{id}")
    public ResponseEntity<ConcentrationEvaluation> getConcentrationEvaluation(@PathVariable Long id) {
        return get(concentrationEvaluationService, id);
    }

    @PostMapping(path = "/concentration-evaluations", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<ConcentrationEvaluation> createConcentrationEvaluation(@RequestBody ConcentrationEvaluation request) {
        return create(concentrationEvaluationService, "/api/concentration-evaluations", request);
    }

    @PutMapping(path = "/concentration-evaluations/{id}", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<ConcentrationEvaluation> updateConcentrationEvaluation(@PathVariable Long id, @RequestBody ConcentrationEvaluation request) {
        return update(concentrationEvaluationService, id, request);
    }

    @DeleteMapping("/concentration-evaluations/{id}")
    public ResponseEntity<Void> deleteConcentrationEvaluation(@PathVariable Long id) {
        return delete(concentrationEvaluationService, id);
    }

    @GetMapping("/concentration-notifications")
    public ResponseEntity<List<ConcentrationNotification>> listConcentrationNotifications() {
        return list(concentrationNotificationService);
    }

    @GetMapping("/concentration-notifications/{id}")
    public ResponseEntity<ConcentrationNotification> getConcentrationNotification(@PathVariable Long id) {
        return get(concentrationNotificationService, id);
    }

    @PostMapping(path = "/concentration-notifications", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<ConcentrationNotification> createConcentrationNotification(@RequestBody ConcentrationNotification request) {
        return create(concentrationNotificationService, "/api/concentration-notifications", request);
    }

    @PutMapping(path = "/concentration-notifications/{id}", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<ConcentrationNotification> updateConcentrationNotification(@PathVariable Long id, @RequestBody ConcentrationNotification request) {
        return update(concentrationNotificationService, id, request);
    }

    @DeleteMapping("/concentration-notifications/{id}")
    public ResponseEntity<Void> deleteConcentrationNotification(@PathVariable Long id) {
        return delete(concentrationNotificationService, id);
    }

    @GetMapping("/collection-cases")
    public ResponseEntity<List<CollectionCase>> listCollectionCases() {
        return list(collectionCaseService);
    }

    @GetMapping("/collection-cases/{id}")
    public ResponseEntity<CollectionCase> getCollectionCase(@PathVariable Long id) {
        return get(collectionCaseService, id);
    }

    @PostMapping(path = "/collection-cases", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<CollectionCase> createCollectionCase(@RequestBody CollectionCase request) {
        return create(collectionCaseService, "/api/collection-cases", request);
