    }

    @DeleteMapping("/collection-cases/{id}")
    public ResponseEntity<Void> deleteCollectionCase(@PathVariable Long id) {
        return delete(collectionCaseService, id);
    }

    @GetMapping("/waiver-approvals")
    public ResponseEntity<List<WaiverApproval>> listWaiverApprovals() {
        return list(waiverApprovalService);
    }

    @GetMapping("/waiver-approvals/{id}")
    public ResponseEntity<WaiverApproval> getWaiverApproval(@PathVariable Long id) {
        return get(waiverApprovalService, id);
    }

    @PostMapping(path = "/waiver-approvals", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<WaiverApproval> createWaiverApproval(@RequestBody WaiverApproval request) {
        return create(waiverApprovalService, "/api/waiver-approvals", request);
    }

    @PutMapping(path = "/waiver-approvals/{id}", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<WaiverApproval> updateWaiverApproval(@PathVariable Long id, @RequestBody WaiverApproval request) {
        return update(waiverApprovalService, id, request);
    }

    @DeleteMapping("/waiver-approvals/{id}")
    public ResponseEntity<Void> deleteWaiverApproval(@PathVariable Long id) {
        return delete(waiverApprovalService, id);
    }

    private <T extends BaseEntity> ResponseEntity<List<T>> list(CrudService<T> service) {
        return ResponseEntity.ok(service.findAll());
    }

    private <T extends BaseEntity> ResponseEntity<T> get(CrudService<T> service, Long id) {
        return ResponseEntity.ok(service.getRequired(id));
    }

    private <T extends BaseEntity> ResponseEntity<T> create(CrudService<T> service, String basePath, T request) {
        T created = service.create(request);
        return ResponseEntity.created(URI.create(basePath + "/" + created.getId())).body(created);
    }

    private <T extends BaseEntity> ResponseEntity<T> update(CrudService<T> service, Long id, T request) {
        return ResponseEntity.ok(service.update(id, request));
    }

    private <T extends BaseEntity> ResponseEntity<Void> delete(CrudService<T> service, Long id) {
        service.deleteById(id);
        return ResponseEntity.noContent().build();
    }
}

