package rs.ucb.komo.settings.controller;

import static org.springframework.http.MediaType.APPLICATION_JSON_VALUE;

import java.net.URI;
import java.util.List;

import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import rs.ucb.komo.settings.model.BaseEntity;
import rs.ucb.komo.settings.model.NotificationRecipientConfig;
import rs.ucb.komo.settings.model.SignalSetting;
import rs.ucb.komo.settings.service.CrudService;
import rs.ucb.komo.settings.service.NotificationRecipientConfigService;
import rs.ucb.komo.settings.service.SignalSettingService;

@RestController
@RequestMapping(path = "/api", produces = APPLICATION_JSON_VALUE)
@ConditionalOnBean(name = "entityManagerFactory")
public class SettingsDataController {

    private final SignalSettingService signalSettingService;
    private final NotificationRecipientConfigService notificationRecipientConfigService;

    public SettingsDataController(
            SignalSettingService signalSettingService,
            NotificationRecipientConfigService notificationRecipientConfigService) {
        this.signalSettingService = signalSettingService;
        this.notificationRecipientConfigService = notificationRecipientConfigService;
    }

    @GetMapping("/signal-settings")
    public ResponseEntity<List<SignalSetting>> listSignalSettings() {
        return list(signalSettingService);
    }

    @GetMapping("/signal-settings/{id}")
    public ResponseEntity<SignalSetting> getSignalSetting(@PathVariable Long id) {
        return get(signalSettingService, id);
    }

    @PostMapping(path = "/signal-settings", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<SignalSetting> createSignalSetting(@RequestBody SignalSetting request) {
        return create(signalSettingService, "/api/signal-settings", request);
    }

    @PutMapping(path = "/signal-settings/{id}", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<SignalSetting> updateSignalSetting(
            @PathVariable Long id,
            @RequestBody SignalSetting request) {
        return update(signalSettingService, id, request);
    }

    @DeleteMapping("/signal-settings/{id}")
    public ResponseEntity<Void> deleteSignalSetting(@PathVariable Long id) {
        return delete(signalSettingService, id);
    }

    @GetMapping("/notification-recipient-configs")
    public ResponseEntity<List<NotificationRecipientConfig>> listNotificationRecipientConfigs() {
        return list(notificationRecipientConfigService);
    }

    @GetMapping("/notification-recipient-configs/{id}")
    public ResponseEntity<NotificationRecipientConfig> getNotificationRecipientConfig(@PathVariable Long id) {
        return get(notificationRecipientConfigService, id);
    }

    @PostMapping(path = "/notification-recipient-configs", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<NotificationRecipientConfig> createNotificationRecipientConfig(
            @RequestBody NotificationRecipientConfig request) {
        return create(notificationRecipientConfigService, "/api/notification-recipient-configs", request);
    }

    @PutMapping(path = "/notification-recipient-configs/{id}", consumes = APPLICATION_JSON_VALUE)
    public ResponseEntity<NotificationRecipientConfig> updateNotificationRecipientConfig(
            @PathVariable Long id,
            @RequestBody NotificationRecipientConfig request) {
        return update(notificationRecipientConfigService, id, request);
    }

    @DeleteMapping("/notification-recipient-configs/{id}")
    public ResponseEntity<Void> deleteNotificationRecipientConfig(@PathVariable Long id) {
        return delete(notificationRecipientConfigService, id);
    }

    private <T extends BaseEntity> ResponseEntity<List<T>> list(CrudService<T> service) {
        return ResponseEntity.ok(service.findAll());
    }

    private <T extends BaseEntity> ResponseEntity<T> get(CrudService<T> service, Long id) {
        return ResponseEntity.ok(service.getRequired(id));
    }

    private <T extends BaseEntity> ResponseEntity<T> create(CrudService<T> service, String basePath, T request) {
        T created = service.create(request);
        return ResponseEntity.created(URI.create(basePath + "/" + created.getId())).body(created);
    }

    private <T extends BaseEntity> ResponseEntity<T> update(CrudService<T> service, Long id, T request) {
        return ResponseEntity.ok(service.update(id, request));
    }

    private <T extends BaseEntity> ResponseEntity<Void> delete(CrudService<T> service, Long id) {
        service.deleteById(id);
        return ResponseEntity.noContent().build();
    }
}

